/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["gespraech-arbeitsstart"]={"Eine Einladung organisatorisch klären":"روشن کردن سازمانی یک دعوت","Du bestätigst einen Gesprächstermin und prüfst Ort, Format und benötigte Vorbereitung.":"شما وقت مصاحبه را تأیید می‌کنید و جا، شکل و آمادگی لازم را بررسی می‌کنید.","Videoeinladung als Vor-Ort-Termin lesen":"دعوت ویدیویی را ملاقات حضوری خواندن","Falsch: Ohne Prüfung am Empfang erscheinen, obwohl ein Videogespräch vereinbart ist. Richtig: Format und Ort aus der Einladung übernehmen.":"اشتباه: بدون بررسی در پذیرش حاضر شوید، با اینکه یک گفتگوی ویدیویی توافق شده است. درست: شکل و جا را از دعوت‌نامه بگیرید.","Freude mit Terminbestätigung gleichsetzen":"خوشحالی را تأیید وقت دانستن","Falsch: Nur „Ich freue mich“ schreiben und die Verfügbarkeit offenlassen. Richtig: Den konkreten Termin ausdrücklich bestätigen oder Alternativen erbitten.":"اشتباه: فقط „Ich freue mich“ (خوشحالم) بنویسید و در دسترس بودن را باز بگذارید. درست: وقت مشخص را صریحاً تأیید کنید یا وقت‌های دیگر بخواهید.","Welches Format ist vereinbart?":"کدام شکل توافق شده است؟","Videogespräch.":"گفتگوی ویدیویی.","Ein persönlicher Termin im Betrieb.":"یک ملاقات حضوری در شرکت.","Ein Telefongespräch ohne Videozugang.":"یک گفتگوی تیلفونی بدون دسترسی ویدیویی.","Die Einladung nennt ausdrücklich ein Videogespräch.":"دعوت‌نامه صریحاً یک گفتگوی ویدیویی را نام می‌برد.","Wann soll Amin den Link erhalten?":"امین لینک را چه وقت باید بگیرد؟","Erst unmittelbar nach Beginn des Gesprächs.":"فقط درست بعد از شروع گفتگو.","Am Vortag.":"روز قبل.","Zusammen mit einer späteren Vertragszusage.":"همراه با یک قبولی بعدی قرارداد.","Die Personalstelle sagt den Versand des Links am Vortag zu.":"بخش کارکنان فرستادن لینک را برای روز قبل وعده می‌دهد.","Welche Antwort bestätigt den Termin klar?":"کدام جواب وقت را روشن تأیید می‌کند؟","Vielen Dank, ich freue mich auf eine spätere Rückmeldung.":"سپاس، منتظر یک جواب بعدی هستم.","Vielen Dank, bitte halten Sie mich über mögliche Termine auf dem Laufenden.":"سپاس، لطفاً مرا از وقت‌های ممکن باخبر نگه دارید.","Vielen Dank, ich bestätige Mittwoch um 10 Uhr.":"سپاس، چهارشنبه ساعت 10 را تأیید می‌کنم.","Die konkrete Zeit und ausdrückliche Bestätigung machen die Verfügbarkeit eindeutig.":"وقت مشخص و تأیید صریح در دسترس بودن را روشن می‌کند.","Übertrage Datum, Uhrzeit und Kontaktperson aus der Einladung in eine eigene kurze Terminnotiz.":"تاریخ، ساعت و شخص تماس را از دعوت‌نامه در یک یادداشت کوتاه وقت خودتان بنویسید.","Einen Termin bestätigen":"تأیید یک وقت","Personalstelle: „Wir laden Sie am Mittwoch um 10 Uhr zum Videogespräch ein.“ Amin: „Vielen Dank. Ich bestätige den Termin. Erhalte ich den Zugangslink noch?“ Personalstelle: „Ja, am Vortag.“ Amin: „An wen kann ich mich bei einem technischen Problem wenden?“ Er klärt das Format und den Kontakt, statt stillschweigend einen Besuch im Betrieb zu planen.":"بخش کارکنان: «شما را چهارشنبه ساعت 10 به گفتگوی ویدیویی دعوت می‌کنیم.» امین: «سپاس. وقت را تأیید می‌کنم. آیا لینک دسترسی را هم می‌گیرم؟» بخش کارکنان: «بله، روز قبل.» امین: «در صورت مشکل فنی به چه کسی مراجعه کنم؟» او شکل و تماس را روشن می‌کند، به جای اینکه بی‌صدا یک رفتن به شرکت را برنامه‌ریزی کند.","Bestätigen und nachfragen verbinden":"وصل کردن تأیید و پرسیدن","Eine Antwort kann mit Dank und ausdrücklicher Bestätigung beginnen. Fehlt eine wesentliche Angabe, stellst du eine konkrete Rückfrage. „Ich freue mich auf das Gespräch“ allein beantwortet nicht unbedingt, ob du den genannten Termin wahrnehmen kannst. Wenn du verhindert bist, nenne die Verhinderung rechtzeitig und schlage mögliche Alternativen vor.":"یک جواب می‌تواند با سپاس و تأیید صریح شروع شود. اگر یک معلومات مهم کم است، یک سوال مشخص می‌پرسید. „Ich freue mich auf das Gespräch“ (منتظر گفتگو هستم) به تنهایی لزوماً جواب نمی‌دهد که آیا می‌توانید در وقت نام‌برده حاضر شوید. اگر نمی‌توانید، به‌موقع آن را بگویید و وقت‌های ممکن دیگر پیشنهاد کنید.","Format und Anfahrt getrennt prüfen":"بررسی جداگانهٔ شکل و راه رسیدن","Prüfe für ein Videogespräch Kamera, Mikrofon und einen ruhigen Platz. Bei einem Besuch brauchst du den richtigen Eingang und die Anfahrt. Ein Zugangslink muss zum bestätigten Absender passen. Verlangt die Nachricht eine unerwartete Installation, frage beim bekannten Kontakt nach. Halte dessen Telefonnummer für Probleme bereit.":"برای یک گفتگوی ویدیویی کمره، میکروفون و یک جای آرام را بررسی کنید. برای یک ملاقات حضوری دروازهٔ درست و راه رسیدن را لازم دارید. یک لینک دسترسی باید با فرستندهٔ تأییدشده جور باشد. اگر پیام یک نصب غیرمنتظره می‌خواهد، از تماس شناخته‌شده بپرسید. شمارهٔ تیلفون او را برای مشکلات آماده نگه دارید.","Einen überschaubaren Techniktest machen":"انجام یک آزمایش سادهٔ فنی","Teste Kamera und Mikrofon vor dem Termin und lege die Unterlagen bereit. Vermeide einen sichtbaren Bildschirm mit fremden persönlichen Daten. Eine funktionierende Technik gestern garantiert den heutigen Zugang nicht; halte deshalb die bestätigte Kontaktmöglichkeit bereit. Falls der zugesagte Link fehlt, frage gezielt nach und dokumentiere die Antwort.":"کمره و میکروفون را پیش از وقت آزمایش کنید و اسناد را آماده بگذارید. از یک صفحهٔ قابل دید با معلومات شخصی دیگران پرهیز کنید. کار کردن فنی دیروز دسترسی امروز را تضمین نمی‌کند؛ پس راه تماس تأییدشده را آماده نگه دارید. اگر لینک وعده‌شده نیامد، هدفمند بپرسید و جواب را ثبت کنید.","Die Termindaten ergänzen":"کامل کردن معلومات وقت","Setze „Mittwoch“ und „10“ ein.":"„Mittwoch“ (چهارشنبه) و „10“ را بگذارید.","Übernimm Tag und Uhrzeit aus der Einladung.":"روز و ساعت را از دعوت‌نامه بگیرید.","Beide Angaben gehören zur eindeutigen Bestätigung.":"هر دو معلومات به یک تأیید روشن تعلق دارند.","Das Gespräch ist am ___.":"Das Gespräch ist am ___. (گفتگو روز ___ است.)","Beginn ist um ___ Uhr.":"Beginn ist um ___ Uhr. (شروع ساعت ___ است.)","Vorbereitung passend zuordnen":"وصل کردن مناسب آمادگی","Verbinde Format und Vorbereitung.":"شکل و آمادگی را وصل کنید.","Richte die Vorbereitung am tatsächlichen Format aus.":"آمادگی را بر اساس شکل واقعی تنظیم کنید.","Die Anforderungen unterscheiden sich nach Gesprächsart.":"خواسته‌ها بر اساس نوع گفتگو فرق دارند.","Videogespräch":"گفتگوی ویدیویی","Besuch im Betrieb":"ملاقات در شرکت","fehlender Link":"لینک کم","Die Uhrzeit hören":"شنیدن ساعت","Um wie viel Uhr beginnt das Gespräch? Antworte als Zahl.":"گفتگو چه ساعتی شروع می‌شود؟ به عدد جواب دهید.","Der Versandtag des Links ist nicht der Gesprächsbeginn.":"روز فرستادن لینک شروع گفتگو نیست.","Das Gespräch startet am Mittwoch um 10 Uhr.":"گفتگو چهارشنبه ساعت 10 شروع می‌شود.","Eine Einladung beantworten":"جواب دادن به یک دعوت","Bestätige Mittwoch um 10 Uhr per Video und frage nach dem Kontakt bei Zugangsproblemen.":"چهارشنبه ساعت 10 از راه ویدیو را تأیید کنید و دربارهٔ تماس در صورت مشکل دسترسی بپرسید.","Gib nur die vereinbarten Angaben als feststehend wieder.":"فقط معلومات توافق‌شده را قطعی بنویسید.","Die Antwort verbindet Bestätigung und organisatorische Rückfrage.":"این جواب تأیید و پرسش سازمانی را وصل می‌کند.","Ist das Videoformat ausdrücklich genannt?":"آیا شکل ویدیویی صریحاً نام برده شده است؟","Bestätigst du Mittwoch um 10 Uhr?":"آیا چهارشنبه ساعت 10 را تأیید می‌کنید؟","Bleibt der Linkversand am Vortag richtig wiedergegeben?":"آیا فرستادن لینک در روز قبل درست نوشته می‌ماند؟","Fragst du nach einem konkreten Kontakt bei Problemen?":"آیا دربارهٔ یک تماس مشخص در صورت مشکل می‌پرسید؟","Eine Terminbestätigung nennt den tatsächlich angebotenen Termin.":"یک تأیید وقت، وقت واقعاً پیشنهادشده را نام می‌برد.","Ein geklärter Kontaktweg hilft bei fehlenden Zugangsdaten.":"یک راه تماس روشن‌شده در نبود معلومات دسترسی کمک می‌کند.","Sich in kurzer Form vorstellen":"معرفی کوتاه خود","Du wählst relevante Stationen und erklärst den Bezug zur ausgeschriebenen Aufgabe.":"شما بخش‌های مربوط را انتخاب می‌کنید و ربط آن‌ها را با کار اعلان‌شده توضیح می‌دهید.","Eine vollständige Lebensgeschichte vortragen":"گفتن تمام داستان زندگی","Falsch: Mehrere Minuten ohne Stellenbezug erzählen. Richtig: Relevante Station, konkretes Beispiel und Interesse kurz verbinden.":"اشتباه: چند دقیقه بدون ربط با کار حرف زدن. درست: یک بخش مربوط، یک مثال مشخص و علاقه را کوتاه وصل کنید.","Selbstständigkeit ungeprüft behaupten":"ادعای بررسی‌نشدهٔ کار مستقل","Falsch: Alle Aufgaben als allein verantwortlich darstellen. Richtig: Den tatsächlichen Umfang der eigenen Arbeit nennen.":"اشتباه: همهٔ کارها را با مسئولیت تنها نشان دادن. درست: اندازهٔ واقعی کار خودتان را نام ببرید.","Welches Beispiel nennt Sara als selbstständig übernommen?":"سارا کدام مثال را کار مستقل خود می‌نامد؟","Die gesamte Warenbestellung des Betriebs.":"تمام سفارش کالای شرکت.","Die vollständige Organisation aller Beratungsschichten.":"سازمان‌دهی کامل همهٔ نوبت‌های مشوره.","Die wöchentliche Bestandsliste.":"لست هفته‌وار موجودی.","Sara grenzt ihre selbstständige Aufgabe auf die Bestandsliste ein.":"سارا کار مستقل خود را به لست موجودی محدود می‌کند.","Was gehört in eine kurze Vorstellung?":"چه چیزی در یک معرفی کوتاه جا دارد؟","Relevante Tätigkeit und Bezug zur Stelle.":"کار مربوط و ربط با کار اعلان‌شده.","Eine chronologische Aufzählung aller privaten Stationen.":"یک شمارش زمانی همهٔ بخش‌های خصوصی.","Nur eine Liste von Eigenschaften ohne Bezug zur Tätigkeit.":"فقط یک لست ویژگی‌ها بدون ربط با کار.","Auswahl und Stellenbezug machen die Vorstellung für das Gespräch nützlich.":"انتخاب و ربط با کار معرفی را برای گفتگو مفید می‌کنند.","Warum laut üben?":"چرا بلند تمرین کنیم؟","Damit auf jede Frage derselbe auswendig gelernte Text folgt.":"تا بعد از هر سوال همان متن حفظ‌شده بیاید.","Damit Verständlichkeit und Länge hörbar werden.":"تا قابل فهم بودن و طول شنیده شود.","Damit alle Stationen ohne Auswahl vollständig erwähnt werden.":"تا همهٔ بخش‌ها بدون انتخاب کامل گفته شوند.","Mündliches Erproben zeigt, ob die Kernaussagen tatsächlich ankommen.":"آزمایش شفاهی نشان می‌دهد که آیا گفته‌های اصلی واقعاً می‌رسند.","Übe eine Vorstellung mit bisheriger Tätigkeit, einem Beispiel und dem Interesse an der neuen Aufgabe.":"یک معرفی با کار تا حالا، یک مثال و علاقه به کار تازه تمرین کنید.","Eine kurze Vorstellung beginnen":"شروع یک معرفی کوتاه","Interviewer: „Erzählen Sie uns etwas über sich.“ Sara: „Ich habe zuletzt in einem kleinen Geschäft gearbeitet. Dort habe ich Waren bestellt und Kunden beraten. An Ihrer Stelle interessiert mich besonders die Verbindung von Beratung und Organisation.“ Interviewer: „Welche Aufgabe haben Sie selbstständig übernommen?“ Sara: „Die wöchentliche Bestandsliste.“":"مصاحبه‌گر: «کمی دربارهٔ خودتان بگویید.» سارا: «آخرین بار در یک دکان کوچک کار کردم. آنجا کالا سفارش دادم و به مشتریان مشوره دادم. در کار شما به‌خصوص پیوند مشوره و سازمان‌دهی برایم جالب است.» مصاحبه‌گر: «کدام کار را مستقل انجام داده‌اید؟» سارا: «لست هفته‌وار موجودی.»","Relevante Auswahl treffen":"انتخاب مربوط","Eine Selbstvorstellung ist keine vollständige Lebensgeschichte. Wähle Angaben, die den Bezug zur Stelle erklären. Beginne mit einer passenden Station, nenne eine konkrete Tätigkeit und verbinde sie mit deinem Interesse. Zwei klare Beispiele helfen mehr als eine Reihe großer Eigenschaften. Die Darstellung soll mit dem Lebenslauf übereinstimmen und darf durch Übung kürzer, aber nicht erfunden werden.":"یک معرفی خود داستان کامل زندگی نیست. معلوماتی را انتخاب کنید که ربط با کار را توضیح می‌دهند. با یک بخش مناسب شروع کنید، یک کار مشخص نام ببرید و آن را با علاقهٔ خود وصل کنید. دو مثال روشن بیشتر از یک ردیف ویژگی‌های بزرگ کمک می‌کنند. توضیح باید با رزومه جور باشد و با تمرین می‌تواند کوتاه‌تر شود، اما نباید ساختگی شود.","Mit Verben konkret werden":"مشخص شدن با فعل‌ها","Beschreibe deinen Beitrag mit Verben. „Ich erstellte jede Woche die Bestandsliste“ ist genauer als „Ich war für alles zuständig“. Sage, welche Aufgabe du selbst erledigt hast. Hast du dabei Hilfe gebraucht, nenne das ebenfalls. Eine kurze, genaue Beschreibung zeigt mehr als ein großer Titel ohne Beispiel.":"سهم خود را با فعل‌ها توصیف کنید. „Ich erstellte jede Woche die Bestandsliste“ (هر هفته لست موجودی را ساختم) دقیق‌تر از „Ich war für alles zuständig“ (من مسئول همه چیز بودم) است. بگویید کدام کار را خودتان انجام داده‌اید. اگر در آن کمک لازم داشتید، آن را هم بگویید. یک توضیح کوتاه و دقیق بیشتر از یک عنوان بزرگ بدون مثال نشان می‌دهد.","Die Vorstellung mündlich erproben":"آزمایش شفاهی معرفی","Sprich die Vorstellung laut, statt sie nur still zu lesen. Bitte eine andere Person, deine wichtigsten Tätigkeiten zu wiederholen. Fehlen sie in ihrer Erinnerung, kürze Nebensachen und ordne die Hauptpunkte neu. Lerne nicht jeden Satz starr auswendig; ein Gespräch kann nach dem ersten Satz eine Rückfrage enthalten. Bleibe dann bei der tatsächlichen Erfahrung.":"معرفی را بلند بگویید، به جای اینکه فقط آرام بخوانید. از شخص دیگری بخواهید که مهم‌ترین کارهای شما را تکرار کند. اگر در یادش نیستند، چیزهای فرعی را کوتاه کنید و نکته‌های اصلی را دوباره مرتب کنید. هر جمله را خشک حفظ نکنید؛ یک گفتگو ممکن است بعد از جملهٔ اول یک سوال داشته باشد. آن وقت به تجربهٔ واقعی بسنده کنید.","Tätigkeiten ergänzen":"کامل کردن کارها","Setze „beraten“ und „Bestandsliste“ ein.":"„beraten“ (مشوره داده) و „Bestandsliste“ (لست موجودی) را بگذارید.","Unterscheide Kundenkontakt und organisatorische Aufgabe.":"تماس با مشتری و کار سازمانی را جدا کنید.","Die zwei Beispiele konkretisieren ihren beruflichen Hintergrund.":"این دو مثال پیشینهٔ کاری او را مشخص می‌کنند.","Sara hat Kunden ___.":"Sara hat Kunden ___. (سارا به مشتریان ___.)","Sie erstellte die wöchentliche ___.":"Sie erstellte die wöchentliche ___. (او ___ هفته‌وار را ساخت.)","Vorstellungsbausteine zuordnen":"وصل کردن بخش‌های معرفی","Ordne die Aussagen zu.":"گفته‌ها را وصل کنید.","Drei unterschiedliche Bausteine ergeben einen kurzen Zusammenhang.":"سه بخش مختلف یک پیوند کوتاه می‌سازند.","Die Vorstellung führt vom Hintergrund zur neuen Aufgabe.":"معرفی از پیشینه به کار تازه می‌رسد.","Ich arbeitete im Geschäft.":"من در دکان کار کردم.","Ich erstellte Bestandslisten.":"من لست‌های موجودی ساختم.","Mich reizt die Organisation.":"سازمان‌دهی مرا جذب می‌کند.","Die Häufigkeit hören":"شنیدن تکرار","Wie oft erstellte Sara die Bestandsliste? Antworte mit einem Adverb.":"سارا لست موجودی را هر چند وقت یک بار می‌ساخت؟ با یک قید (به آلمانی) جواب دهید.","Gefragt ist die Bestandsliste, nicht die Beratung.":"لست موجودی پرسیده شده، نه مشوره.","Die Bestandsliste wurde einmal pro Woche erstellt.":"لست موجودی هفته‌ای یک بار ساخته می‌شد.","Eine kurze Vorstellung verfassen":"نوشتن یک معرفی کوتاه","Formuliere drei bis vier Sätze mit Saras Station, Tätigkeiten und Interesse.":"سه تا چهار جمله با بخش کاری، کارها و علاقهٔ سارا بنویسید.","Sprich den Entwurf anschließend laut und prüfe die Verständlichkeit.":"بعد پیش‌نویس را بلند بگویید و قابل فهم بودن را بررسی کنید.","Die Vorstellung ist kurz, konkret und mit den Angaben des Dialogs vereinbar.":"این معرفی کوتاه، مشخص و با معلومات گفتگو جور است.","Ist die passende Station genannt?":"آیا بخش مناسب نام برده شده است؟","Beschreibst du konkrete statt pauschale Tätigkeiten?":"آیا کارهای مشخص را به جای کلی توصیف می‌کنید؟","Bleibt die selbstständige Aufgabe auf die Bestandsliste begrenzt?":"آیا کار مستقل به لست موجودی محدود می‌ماند؟","Erklärst du den Bezug zur neuen Stelle?":"آیا ربط با کار تازه را توضیح می‌دهید؟","Eine Selbstvorstellung wählt passende Informationen statt alles aufzuzählen.":"یک معرفی خود معلومات مناسب را انتخاب می‌کند، به جای اینکه همه چیز را بشمارد.","Konkrete Verben machen den eigenen Beitrag erkennbar.":"فعل‌های مشخص سهم خودتان را قابل دید می‌کنند.","Stärken mit einer Situation belegen":"ثابت کردن توانایی‌ها با یک وضعیت","Du beschreibst Situation, eigene Handlung und Ergebnis, ohne den Beitrag des Teams zu vereinnahmen.":"شما وضعیت، کار خود و نتیجه را توصیف می‌کنید، بدون اینکه سهم گروه را از آن خود کنید.","Ein Teamergebnis allein beanspruchen":"نتیجهٔ گروه را تنها ادعا کردن","Falsch: „Ich entschied alles allein“, obwohl das Team die Abweichung klärte. Richtig: Eigene Kontrolle und gemeinsame Klärung auseinanderhalten.":"اشتباه: „Ich entschied alles allein“ (همه چیز را تنها تصمیم گرفتم)، با اینکه گروه تفاوت را روشن کرد. درست: کنترول خودتان و روشن‌سازی مشترک را جدا نگه دارید.","Eine Erfolgszahl erfinden":"ساختن یک عدد موفقیت","Falsch: Ohne Messung eine angebliche Einsparung von 80 Prozent nennen. Richtig: Das tatsächlich beobachtete Ergebnis beschreiben.":"اشتباه: بدون اندازه‌گیری یک صرفه‌جویی ادعایی 80 درصد را نام ببرید. درست: نتیجهٔ واقعاً دیده‌شده را توصیف کنید.","Was war Bilals eigener Beitrag?":"سهم خود بلال چه بود؟","Die Nachlieferung selbst genehmigen.":"خودش تحویل بعدی را تأیید کرد.","Menge vergleichen und Abweichung melden.":"مقدار را مقایسه کرد و تفاوت را گزارش داد.","Die Abweichung ohne Abstimmung allein erledigen.":"تفاوت را بدون هماهنگی تنها حل کرد.","Bilal nennt Kontrolle und Meldung ausdrücklich als eigene Handlungen.":"بلال کنترول و گزارش را صریحاً کار خودش می‌نامد.","Welche Ergebnisangabe passt zum Beispiel?":"کدام معلومات نتیجه با مثال جور است؟","Die Abweichung wurde vor der Einlagerung geklärt.":"تفاوت پیش از انبار کردن روشن شد.","Die gesamte Nachlieferung wurde von Bilal entschieden.":"تمام تحویل بعدی را بلال تصمیم گرفت.","Die Kontrolle führte zu einer gemessenen Einsparung von 80 Prozent.":"کنترول به یک صرفه‌جویی اندازه‌گیری‌شدهٔ 80 درصد رسید.","Nur die rechtzeitige Klärung wird im Gespräch tatsächlich beschrieben.":"فقط روشن‌سازی به‌موقع در گفتگو واقعاً توصیف می‌شود.","Wie gehst du mit einer unsicheren Einzelheit um?":"با یک جزئیات نامطمئن چه می‌کنید؟","Eine ungefähre Zahl als sichere Erinnerung nennen.":"یک عدد تقریبی را یک خاطرهٔ مطمئن بنامید.","Die unsichere Einzelheit ohne Hinweis als bestätigt darstellen.":"جزئیات نامطمئن را بدون اشاره تأییدشده نشان دهید.","Die Unsicherheit offen benennen.":"نامطمئن بودن را آشکارا بگویید.","Ein ehrlicher Hinweis ist präziser als eine nicht belegbare Angabe.":"یک اشارهٔ صادقانه دقیق‌تر از یک معلومات غیرقابل اثبات است.","Wähle ein Beispiel, an dem dein eigener Beitrag auch ohne große Eigenschaftswörter sichtbar wird.":"مثالی انتخاب کنید که سهم خودتان در آن بدون صفت‌های بزرگ هم دیده شود.","Ein Beispiel für Sorgfalt nennen":"نام بردن یک مثال برای دقت","Interviewer: „Wann hat Ihnen Ihre sorgfältige Arbeit geholfen?“ Bilal: „Bei einer Lieferung stimmte die Anzahl nicht. Ich verglich Lieferschein und Kartons und meldete die Abweichung. Das Team klärte sie vor der Einlagerung.“ Interviewer: „Was war Ihr Beitrag?“ Bilal: „Die Kontrolle und die Meldung, nicht die Entscheidung über die Nachlieferung.“":"مصاحبه‌گر: «کار دقیق شما چه وقت به شما کمک کرد؟» بلال: «در یک تحویل تعداد درست نبود. رسید تحویل و کارتن‌ها را مقایسه کردم و تفاوت را گزارش دادم. گروه آن را پیش از انبار کردن روشن کرد.» مصاحبه‌گر: «سهم شما چه بود؟» بلال: «کنترول و گزارش، نه تصمیم دربارهٔ تحویل بعدی.»","Ein Beispiel übersichtlich erzählen":"تعریف مرتب یک مثال","Nenne kurz die Situation, danach deine Handlung und zuletzt das Ergebnis. Bei Bilal sind das die unpassende Menge, der Vergleich und die rechtzeitige Klärung im Team. Wenn ein Ergebnis nicht gemessen wurde, erfindest du keine Prozentzahl. „Die Abweichung wurde vor der Einlagerung geklärt“ ist ein belegbarer Ablauf, wenn es tatsächlich so war.":"اول کوتاه وضعیت، بعد کار خودتان و در آخر نتیجه را بگویید. نزد بلال این‌ها مقدار نادرست، مقایسه و روشن‌سازی به‌موقع در گروه هستند. اگر یک نتیجه اندازه‌گیری نشده، هیچ درصدی نمی‌سازید. „Die Abweichung wurde vor der Einlagerung geklärt“ (تفاوت پیش از انبار کردن روشن شد) یک روند قابل اثبات است، اگر واقعاً همین طور بوده است.","Eigenen und gemeinsamen Anteil trennen":"جدا کردن سهم خود و سهم مشترک","Trenne deinen Beitrag von der Arbeit des Teams. Bilal verglich die Kartons und meldete die falsche Menge. Das Team klärte danach die Abweichung. Eine Abweichung ist hier ein Unterschied zwischen Liste und Lieferung. Bilal sollte deshalb nicht behaupten, dass er allein über die Nachlieferung entschieden hat.":"سهم خود را از کار گروه جدا کنید. بلال کارتن‌ها را مقایسه کرد و مقدار نادرست را گزارش داد. گروه بعد از آن تفاوت را روشن کرد. یک تفاوت (Abweichung) اینجا یک فرق بین لست و تحویل است. پس بلال نباید ادعا کند که تنها دربارهٔ تحویل بعدی تصمیم گرفته است.","Auf Nachfragen vorbereitet bleiben":"آماده ماندن برای پرسش‌ها","Überlege, welche Rückfrage dein Beispiel auslösen könnte: Welche Anzahl stand auf dem Lieferschein? Wen hast du informiert? Wenn du eine Einzelheit nicht mehr sicher weißt, sage das offen. Der Sinn der Antwort liegt in deinem nachvollziehbaren Vorgehen. Eine passende Schlussaussage lautet „Deshalb prüfe ich Mengen vor der Einlagerung systematisch“.":"فکر کنید مثال شما کدام سوال را ممکن است پیش بیاورد: روی رسید تحویل چه تعدادی بود؟ به چه کسی خبر دادید؟ اگر یک جزئیات را دیگر مطمئن نمی‌دانید، آشکارا بگویید. معنای جواب در روش قابل پیگیری شماست. یک جملهٔ پایانی مناسب این است: „Deshalb prüfe ich Mengen vor der Einlagerung systematisch“ (به همین دلیل مقدارها را پیش از انبار کردن منظم بررسی می‌کنم).","Den Beitrag ergänzen":"کامل کردن سهم","Setze „verglich“ und „meldete“ ein.":"„verglich“ (مقایسه کرد) و „meldete“ (گزارش داد) را بگذارید.","Beide Verben bezeichnen Bilals eigene Handlungen.":"هر دو فعل کارهای خود بلال را نشان می‌دهند.","Vergleich und Meldung sind sein nachvollziehbarer Beitrag.":"مقایسه و گزارش سهم قابل پیگیری او هستند.","Bilal ___ Lieferschein und Kartons.":"Bilal ___ Lieferschein und Kartons. (بلال رسید تحویل و کارتن‌ها را ___.)","Er ___ die Abweichung.":"Er ___ die Abweichung. (او تفاوت را ___.)","Teile des Beispiels ordnen":"مرتب کردن بخش‌های مثال","Verbinde die Aussage mit dem Baustein.":"گفته را به بخش آن وصل کنید.","Die Reihenfolge erklärt, was zur Lösung beigetragen hat.":"ترتیب توضیح می‌دهد که چه چیزی به حل کمک کرده است.","Die Bausteine zeigen Ausgangspunkt, Vorgehen und beobachtete Wirkung.":"این بخش‌ها نقطهٔ شروع، روش و اثر دیده‌شده را نشان می‌دهند.","Anzahl stimmte nicht":"تعداد درست نبود","Lieferschein vergleichen":"مقایسهٔ رسید تحویل","vor Einlagerung geklärt":"پیش از انبار کردن روشن شد","Den Zeitpunkt der Klärung hören":"شنیدن وقت روشن‌سازی","Vor welchem Arbeitsschritt wurde die Abweichung geklärt?":"تفاوت پیش از کدام قدم کار روشن شد؟","Gesucht ist der nachfolgende Arbeitsschritt.":"قدم کاری بعدی پرسیده شده است.","Die Klärung erfolgte vor der Einlagerung der Waren.":"روشن‌سازی پیش از انبار کردن (Einlagerung) کالاها انجام شد.","Eine Stärke mit Beispiel erklären":"توضیح یک توانایی با مثال","Schreibe vier Sätze zu Situation, Bilals Handlung, Teamergebnis und abgeleiteter Stärke.":"چهار جمله دربارهٔ وضعیت، کار بلال، نتیجهٔ گروه و توانایی برگرفته بنویسید.","Prüfe, ob jede Behauptung auf einer beschriebenen Handlung beruht.":"بررسی کنید که آیا هر ادعا بر یک کار توصیف‌شده استوار است.","Die Antwort macht Sorgfalt an einem nachvollziehbaren Vorgang sichtbar.":"این جواب دقت را در یک روند قابل پیگیری نشان می‌دهد.","Ist die Ausgangssituation knapp erklärt?":"آیا وضعیت شروع کوتاه توضیح داده شده است؟","Nennst du Bilals konkrete eigene Handlungen?":"آیا کارهای مشخص خود بلال را نام می‌برید؟","Bleibt die Klärung als Teamergebnis erkennbar?":"آیا روشن‌سازی به عنوان نتیجهٔ گروه شناخته می‌ماند؟","Leitest du die Stärke aus dem Beispiel statt aus einer erfundenen Zahl ab?":"آیا توانایی را از مثال می‌گیرید، نه از یک عدد ساختگی؟","Situation, Handlung und Ergebnis strukturieren ein anschauliches Beispiel.":"وضعیت، کار و نتیجه یک مثال روشن را ساختار می‌دهند.","Der eigene Beitrag bleibt vom Ergebnis des Teams unterscheidbar.":"سهم خودتان از نتیجهٔ گروه قابل تشخیص می‌ماند.","Über Lernbedarf offen sprechen":"صحبت آشکار دربارهٔ نیاز به یادگیری","Du benennst eine Lücke und verbindest sie mit einem passenden Einarbeitungsschritt.":"شما یک کمبود را نام می‌برید و آن را با یک قدم مناسب آموزش اولیه وصل می‌کنید.","Ähnliche Software als identische Kenntnis ausgeben":"نرم‌افزار مشابه را دانش یکسان جلوه دادن","Falsch: „Ich beherrsche Ihr Programm“, obwohl nur ein anderes bekannt ist. Richtig: Vorwissen nennen und das neue System als Lernbedarf kennzeichnen.":"اشتباه: „Ich beherrsche Ihr Programm“ (برنامهٔ شما را بلدم)، با اینکه فقط یک برنامهٔ دیگر را می‌شناسید. درست: دانش قبلی را نام ببرید و سیستم تازه را نیاز به یادگیری مشخص کنید.","Unkontrolliert im echten System üben":"تمرین بی‌کنترول در سیستم واقعی","Falsch: Ohne Freigabe Testbuchungen in echten Beständen anlegen. Richtig: Geeignete Übungsumgebung und Anleitung klären.":"اشتباه: بدون اجازه ثبت‌های آزمایشی در موجودی واقعی بسازید. درست: محیط تمرین مناسب و راهنمایی را روشن کنید.","Welche Aussage ist ehrlich und hilfreich?":"کدام گفته صادقانه و مفید است؟","Das ist praktisch dasselbe Programm, deshalb beherrsche ich es schon.":"این عملاً همان برنامه است، پس آن را از قبل بلدم.","Das Programm ist neu, deshalb habe ich keine verwertbaren Vorkenntnisse.":"برنامه تازه است، پس هیچ دانش قبلی قابل استفاده ندارم.","Dieses System ist neu; ich habe mit einem anderen Bestände erfasst.":"این سیستم تازه است؛ من با یک سیستم دیگر موجودی ثبت کرده‌ام.","Die Aussage benennt Lücke und vorhandene verwandte Erfahrung getrennt.":"این گفته کمبود و تجربهٔ مشابه موجود را جدا نام می‌برد.","Wo sollte Eva zunächst üben?":"اوا اول کجا باید تمرین کند؟","In einer geklärten Übungsumgebung unter Anleitung.":"در یک محیط تمرین روشن‌شده تحت راهنمایی.","Direkt im laufenden Bestand ohne vorherige Klärung.":"مستقیم در موجودی جاری بدون روشن‌سازی قبلی.","Allein anhand einzelner Bildschirmfotos ohne Rückmeldung.":"تنها با چند عکس صفحه بدون بازخورد.","Ein kontrollierter Übungsweg schützt den Ablauf und ermöglicht Rückfragen.":"یک راه تمرین کنترول‌شده روند کار را محافظت می‌کند و پرسیدن را ممکن می‌کند.","Was macht den Lernplan konkret?":"چه چیزی برنامهٔ یادگیری را مشخص می‌کند؟","Nur die Eigenschaft „Ich lerne schnell“ nennen.":"فقط ویژگی „Ich lerne schnell“ (زود یاد می‌گیرم) را نام بردن.","Ablauf zeigen lassen, Übungsbuchung machen, Eingaben prüfen.":"نشان دادن روند، انجام یک ثبت تمرینی، بررسی نوشته‌ها.","Die Kenntnis des alten Systems als fertige Schulung ausweisen.":"دانش سیستم قدیمی را آموزش کامل‌شده نشان دادن.","Der Plan benennt überprüfbare Handlungen statt einer allgemeinen Eigenschaft.":"این برنامه کارهای قابل بررسی را نام می‌برد، نه یک ویژگی کلی.","Ergänze zu einem Lernbedarf eine konkrete Übung oder Nachfrage, statt nur eine Schwäche zu nennen.":"به یک نیاز یادگیری یک تمرین یا سوال مشخص اضافه کنید، به جای اینکه فقط یک ضعف را نام ببرید.","Eine fehlende Systemkenntnis einordnen":"جا دادن یک دانش کم سیستم","Interviewer: „Kennen Sie unser Warenprogramm?“ Eva: „Dieses Programm habe ich noch nicht benutzt. In meinem letzten Betrieb habe ich mit einem anderen System Bestände erfasst.“ Interviewer: „Wie würden Sie sich einarbeiten?“ Eva: „Ich würde mir den Ablauf zeigen lassen, eine Übungsbuchung unter Anleitung machen und danach die Eingaben prüfen.“":"مصاحبه‌گر: «برنامهٔ کالای ما را می‌شناسید؟» اوا: «این برنامه را هنوز به کار نبرده‌ام. در شرکت قبلی‌ام با یک سیستم دیگر موجودی ثبت کردم.» مصاحبه‌گر: «چطور آن را یاد می‌گرفتید؟» اوا: «می‌خواستم روند را به من نشان دهند، یک ثبت تمرینی تحت راهنمایی انجام دهم و بعد نوشته‌ها را بررسی کنم.»","Vorwissen und Lücke auseinanderhalten":"جدا نگه داشتن دانش قبلی و کمبود","Eine ähnliche Erfahrung kann beim Lernen helfen, ist aber keine bestätigte Kenntnis des neuen Systems. „Ich kenne es noch nicht“ lässt sich mit einem passenden Lernplan verbinden. Unterschätze deine vorhandenen Grundlagen nicht, stelle sie aber auch nicht als bereits absolvierte Produktschulung dar. Nenne die tatsächlich ausgeführte Tätigkeit und die noch neue Oberfläche.":"یک تجربهٔ مشابه می‌تواند در یادگیری کمک کند، اما دانش تأییدشدهٔ سیستم تازه نیست. „Ich kenne es noch nicht“ (هنوز آن را نمی‌شناسم) را می‌توان با یک برنامهٔ یادگیری مناسب وصل کرد. پایه‌های موجود خود را کم نشمارید، اما آن‌ها را آموزش محصول گذرانده‌شده هم نشان ندهید. کار واقعاً انجام‌شده و صفحهٔ هنوز تازه را نام ببرید.","Einen konkreten Lernschritt beschreiben":"توصیف یک قدم مشخص یادگیری","Frage, wo und mit welchen Daten du üben darfst. Eine Übungsbuchung nutzt passende Beispieldaten. Sie darf nicht ungefragt echte Bestände verändern. Lass dir den Ablauf zuerst zeigen. Wiederhole dann einen freigegebenen Schritt unter Anleitung. Vergleiche deine Eingaben mit der Vorgabe und frage bei einem Fehler nach.":"بپرسید کجا و با کدام داده‌ها اجازهٔ تمرین دارید. یک ثبت تمرینی داده‌های نمونهٔ مناسب به کار می‌برد. نباید بی‌پرسش موجودی واقعی را تغییر دهد. اول بگذارید روند را به شما نشان دهند. بعد یک قدم اجازه‌داده‌شده را تحت راهنمایی تکرار کنید. نوشته‌های خود را با نمونه مقایسه کنید و در صورت خطا بپرسید.","Angemessen über Grenzen sprechen":"صحبت مناسب دربارهٔ محدودیت‌ها","Eine ehrliche Lücke ist kein Grund für pauschale Selbstabwertung. „Ich kann nichts“ ignoriert Evas vorhandene Erfahrung. Umgekehrt wäre „Ich beherrsche jede Software“ unbelegt. Sage, was schon gelingt, was neu ist und wie du den nächsten Schritt prüfen würdest. So kann der Betrieb den tatsächlichen Einarbeitungsbedarf einschätzen.":"یک کمبود صادقانه دلیل کوچک شمردن کلی خود نیست. „Ich kann nichts“ (هیچ کاری بلد نیستم) تجربهٔ موجود اوا را نادیده می‌گیرد. برعکس „Ich beherrsche jede Software“ (هر نرم‌افزاری را بلدم) بی‌دلیل است. بگویید چه چیزی از قبل موفق است، چه چیزی تازه است و قدم بعدی را چطور بررسی می‌کنید. به این ترتیب شرکت می‌تواند نیاز واقعی آموزش اولیه را برآورد کند.","Den Lernbedarf ergänzen":"کامل کردن نیاز یادگیری","Setze „neu“ und „Anleitung“ ein.":"„neu“ (تازه) و „Anleitung“ (راهنمایی) را بگذارید.","Trenne unbekanntes System und geplante Unterstützung.":"سیستم ناشناخته و حمایت برنامه‌ریزی‌شده را جدا کنید.","Beide Angaben beschreiben den tatsächlichen Einarbeitungsbedarf.":"هر دو معلومات نیاز واقعی آموزش اولیه را توصیف می‌کنند.","Das konkrete Programm ist für Eva ___.":"Das konkrete Programm ist für Eva ___. (این برنامهٔ مشخص برای اوا ___ است.)","Die erste Übungsbuchung erfolgt unter ___.":"Die erste Übungsbuchung erfolgt unter ___. (اولین ثبت تمرینی تحت ___ انجام می‌شود.)","Lernschritte zuordnen":"وصل کردن قدم‌های یادگیری","Verbinde Handlung und Zweck.":"کار و هدف را وصل کنید.","Jeder Schritt trägt anders zum sicheren Lernen bei.":"هر قدم به شکل دیگری به یادگیری مطمئن کمک می‌کند.","Die Abfolge verbindet Verstehen, Versuch und Prüfung.":"این ترتیب فهمیدن، آزمایش و بررسی را وصل می‌کند.","Ablauf zeigen lassen":"نشان دادن روند","Übungsbuchung durchführen":"انجام ثبت تمرینی","Eingaben vergleichen":"مقایسهٔ نوشته‌ها","Das Vorwissen erfassen":"ثبت دانش قبلی","Was hat Eva im alten System erfasst?":"اوا در سیستم قدیمی چه چیزی را ثبت کرده است؟","Gesucht ist die bekannte Tätigkeit, nicht die ausdrücklich ausgeschlossene.":"کار شناخته‌شده پرسیده شده، نه کاری که صریحاً کنار گذاشته شده.","Eva bringt Erfahrung mit der Bestandserfassung mit.":"اوا تجربهٔ ثبت موجودی (Bestände) دارد.","Einen Lernbedarf formulieren":"نوشتن یک نیاز یادگیری","Schreibe drei Sätze zu Evas Vorwissen, neuer Software und kontrolliertem Lernplan.":"سه جمله دربارهٔ دانش قبلی اوا، نرم‌افزار تازه و برنامهٔ یادگیری کنترول‌شده بنویسید.","Verbinde die Lücke mit einem realistischen nächsten Schritt.":"کمبود را با یک قدم بعدی واقع‌بینانه وصل کنید.","Die Antwort stellt weder Unkenntnis noch Vorwissen übertrieben dar.":"این جواب نه ندانستن و نه دانش قبلی را بزرگ‌نمایی می‌کند.","Nennst du das vorhandene Vorwissen?":"آیا دانش قبلی موجود را نام می‌برید؟","Bleibt das konkrete Programm als neu gekennzeichnet?":"آیا برنامهٔ مشخص تازه علامت زده می‌ماند؟","Ist die Übung als freigegeben und angeleitet beschrieben?":"آیا تمرین اجازه‌داده‌شده و با راهنمایی توصیف شده است؟","Enthält der Plan eine anschließende Kontrolle?":"آیا برنامه یک بررسی بعدی دارد؟","Verwandte Erfahrung ersetzt keine Kenntnis des konkreten Systems.":"تجربهٔ مشابه جای دانش سیستم مشخص را نمی‌گیرد.","Ein Lernplan enthält einen passenden und kontrollierten nächsten Schritt.":"یک برنامهٔ یادگیری یک قدم بعدی مناسب و کنترول‌شده دارد.","Eigene Fragen im Gespräch stellen":"پرسیدن سوال‌های خود در گفتگو","Du fragst nach Aufgaben, Einarbeitung und Arbeitszeiten und hältst offene Punkte fest.":"شما دربارهٔ کارها، آموزش اولیه و ساعت‌های کار می‌پرسید و نکته‌های باز را یادداشت می‌کنید.","Beispiel als dauerhafte Zusage lesen":"مثال را وعدهٔ دائمی خواندن","Falsch: Eine typische Frühschicht als Garantie für alle Einsätze verstehen. Richtig: Beispiel und verbindliche Bedingung getrennt klären.":"اشتباه: یک نوبت صبح معمولی را تضمین برای همهٔ کارها بفهمید. درست: مثال و شرط قطعی را جدا روشن کنید.","Fragen ohne Zuhören ablesen":"خواندن سوال‌ها بدون گوش دادن","Falsch: Bereits beantwortete Punkte kommentarlos erneut abfragen. Richtig: An die Antwort anknüpfen und die tatsächliche Lücke benennen.":"اشتباه: نکته‌های از قبل جواب‌داده‌شده را بی‌توضیح دوباره بپرسید. درست: به جواب وصل شوید و کمبود واقعی را نام ببرید.","Welche Nachfrage konkretisiert die Aufgabenverteilung?":"کدام سوال بعدی تقسیم کارها را مشخص می‌کند؟","Welche Unterlagen sind nach einer Einstellung abzugeben?":"بعد از استخدام کدام اسناد باید داده شوند؟","Könnten Sie eine typische Frühschicht beschreiben?":"می‌توانید یک نوبت صبح معمولی را توصیف کنید؟","Wie viele Personen arbeiten insgesamt im Unternehmen?":"در کل چند نفر در شرکت کار می‌کنند؟","Eine typische Schicht macht die allgemeine Antwort zur Verteilung anschaulich.":"یک نوبت معمولی جواب کلی دربارهٔ تقسیم را روشن می‌کند.","Was darf Jonas aus der Antwort ableiten?":"یوناس از جواب چه چیزی را می‌تواند نتیجه بگیرد؟","Diese Reihenfolge gilt als feste Zusage für jede spätere Schicht.":"این ترتیب وعدهٔ قطعی برای هر نوبت بعدی است.","Kundenberatung gehört nicht zur beschriebenen Tätigkeit.":"مشورهٔ مشتری جزو کار توصیف‌شده نیست.","In der beschriebenen Frühschicht beginnt es mit Warenpflege.":"در نوبت صبح توصیف‌شده کار با رسیدگی به کالا شروع می‌شود.","Die Antwort erklärt ein Beispiel und keine Garantie für sämtliche Einsätze.":"این جواب یک مثال را توضیح می‌دهد و تضمینی برای همهٔ کارها نیست.","Was hilft bei einer entscheidenden offenen Bedingung?":"در یک شرط باز تعیین‌کننده چه چیزی کمک می‌کند؟","Gezielt nach der konkreten Regelung fragen.":"هدفمند دربارهٔ قاعدهٔ مشخص پرسیدن.","Die Regelung aus einer typischen Beispielschicht ableiten.":"قاعده را از یک نوبت نمونهٔ معمولی نتیجه گرفتن.","Die erwünschte Bedingung ohne Rückmeldung als gegeben annehmen.":"شرط دلخواه را بدون جواب موجود فرض کردن.","Ein wichtiger offener Punkt braucht eine ausdrückliche Klärung.":"یک نکتهٔ باز مهم یک روشن‌سازی صریح لازم دارد.","Wähle zwei Fragen, deren Antworten für die Entscheidung über diese Stelle wirklich wichtig sind.":"دو سوال انتخاب کنید که جوابشان برای تصمیم دربارهٔ این کار واقعاً مهم است.","Eine Aufgabenverteilung klären":"روشن کردن تقسیم کارها","Personalreferentin: „Haben Sie noch Fragen?“ Jonas: „Wie verteilen sich Kundenberatung und Warenpflege im Alltag?“ Referentin: „Das hängt von der Schicht ab.“ Jonas: „Könnten Sie mir eine typische Frühschicht beschreiben?“ Referentin: „Zuerst wird Ware eingeräumt, später beraten Sie Kunden.“ Jonas fragt konkret nach, statt eine unklare Antwort als vollständige Erklärung abzuhaken.":"کارمند بخش کارکنان: «سوال دیگری دارید؟» یوناس: «مشورهٔ مشتری و رسیدگی به کالا در کار روزمره چطور تقسیم می‌شوند؟» کارمند: «این به نوبت بستگی دارد.» یوناس: «می‌توانید یک نوبت صبح معمولی را برایم توصیف کنید؟» کارمند: «اول کالا چیده می‌شود، بعد به مشتریان مشوره می‌دهید.» یوناس مشخص می‌پرسد، به جای اینکه یک جواب نامشخص را توضیح کامل حساب کند.","Fragen aus dem Informationsbedarf wählen":"انتخاب سوال‌ها از نیاز به معلومات","Eine gute eigene Frage knüpft an eine tatsächliche Lücke an. „Wie läuft die Einarbeitung ab?“ oder „Wie früh wird der Dienstplan bekanntgegeben?“ betreffen den Alltag. Frage nicht etwas, das gerade ausführlich beantwortet wurde, ohne darauf Bezug zu nehmen. Eine präzise Nachfrage zeigt besseres Zuhören als eine lange vorbereitete Liste ohne Verbindung zum Gespräch.":"یک سوال خوب خودتان به یک کمبود واقعی وصل می‌شود. „Wie läuft die Einarbeitung ab?“ (آموزش اولیه چطور پیش می‌رود؟) یا „Wie früh wird der Dienstplan bekanntgegeben?“ (برنامهٔ کار چقدر زودتر اعلام می‌شود؟) به کار روزمره مربوط‌اند. چیزی را که همین حالا مفصل جواب داده شد نپرسید، بدون اینکه به آن اشاره کنید. یک سوال دقیق گوش دادن بهتری نشان می‌دهد تا یک لست طولانی آماده بدون ربط با گفتگو.","Unbekannte Bedingungen dokumentieren":"ثبت شرط‌های نامعلوم","Ein Dienstplan zeigt, wann du eingesetzt wirst. Frage, wie früh du ihn bekommst und wie Änderungen mitgeteilt werden. Die Beschreibung einer typischen Frühschicht ist noch keine feste Zusage für jeden Tag. Ist eine Zeit für dich entscheidend, bitte um eine klare Auskunft. Notiere, was bestätigt und was noch offen ist.":"یک برنامهٔ کار (Dienstplan) نشان می‌دهد که چه وقت کار می‌کنید. بپرسید چقدر زودتر آن را می‌گیرید و تغییرها چطور اطلاع داده می‌شوند. توصیف یک نوبت صبح معمولی هنوز وعدهٔ قطعی برای هر روز نیست. اگر یک وقت برایتان تعیین‌کننده است، یک جواب روشن بخواهید. یادداشت کنید چه چیزی تأیید شده و چه چیزی هنوز باز است.","Nach der Antwort zusammenfassen":"خلاصه کردن بعد از جواب","Mit „Habe ich richtig verstanden, dass …?“ kannst du prüfen, ob du die Antwort korrekt erfasst hast. In der indirekten Wiedergabe bleibt das Verb am Schluss. Ein Gespräch dient auch deiner Einschätzung der Stelle. Bleibt etwas offen, notiere, wer dazu noch antwortet. Eine unbeantwortete Frage ist weder automatisch Zustimmung noch Ablehnung.":"با „Habe ich richtig verstanden, dass …?“ (آیا درست فهمیدم که …؟) می‌توانید بررسی کنید که آیا جواب را درست گرفته‌اید. در نقل غیرمستقیم فعل در آخر می‌ماند. یک گفتگو به ارزیابی خود شما از کار هم کمک می‌کند. اگر چیزی باز ماند، یادداشت کنید چه کسی هنوز دربارهٔ آن جواب می‌دهد. یک سوال بی‌جواب خودکار نه موافقت است و نه رد.","Eine Rückfrage ergänzen":"کامل کردن یک سوال بعدی","Setze „Frühschicht“ und „dass“ ein.":"„Frühschicht“ (نوبت صبح) و „dass“ را بگذارید.","Der zweite Satz gibt den Inhalt einer Antwort wieder.":"جملهٔ دوم محتوای یک جواب را نقل می‌کند.","Die Rückfrage prüft eine konkrete Beschreibung der Frühschicht.":"این سوال بعدی یک توصیف مشخص از نوبت صبح را بررسی می‌کند.","Bitte beschreiben Sie eine typische ___.":"Bitte beschreiben Sie eine typische ___. (لطفاً یک ___ معمولی را توصیف کنید.)","Habe ich richtig verstanden, ___ zuerst Ware eingeräumt wird?":"Habe ich richtig verstanden, ___ zuerst Ware eingeräumt wird? (آیا درست فهمیدم ___ اول کالا چیده می‌شود؟)","Fragen ihrem Thema zuordnen":"وصل کردن سوال‌ها به موضوعشان","Verbinde Frage und Informationsbereich.":"سوال و بخش معلومات را وصل کنید.","Wähle Fragen nach dem eigenen tatsächlichen Informationsbedarf.":"سوال‌ها را بر اساس نیاز واقعی خودتان به معلومات انتخاب کنید.","Die Themen betreffen verschiedene Seiten des Arbeitsalltags.":"این موضوع‌ها به جنبه‌های مختلف کار روزمره مربوط‌اند.","Wie läuft die Einarbeitung?":"آموزش اولیه چطور پیش می‌رود؟","Wann kommt der Dienstplan?":"برنامهٔ کار چه وقت می‌آید؟","Wie verteilen sich die Aufgaben?":"کارها چطور تقسیم می‌شوند؟","Den ersten Schritt hören":"شنیدن قدم اول","Was wird zu Beginn der beschriebenen Frühschicht eingeräumt?":"در شروع نوبت صبح توصیف‌شده چه چیزی چیده می‌شود؟","Die Frage betrifft den ersten Teil der Beispielschicht.":"سوال به بخش اول نوبت نمونه مربوط است.","Der Ablauf beginnt in diesem Beispiel mit Warenpflege.":"در این مثال روند با رسیدگی به کالا (Ware) شروع می‌شود.","Zwei eigene Fragen vorbereiten":"آماده کردن دو سوال خود","Schreibe zwei Fragen zur Einarbeitung und zum Dienstplan und erkläre in zwei Sätzen, warum du sie stellst.":"دو سوال دربارهٔ آموزش اولیه و برنامهٔ کار بنویسید و در دو جمله توضیح دهید که چرا آن‌ها را می‌پرسید.","Wähle Fragen, deren Antwort deine Entscheidung tatsächlich beeinflusst.":"سوال‌هایی انتخاب کنید که جوابشان واقعاً بر تصمیم شما اثر دارد.","Die Vorbereitung verbindet sachliche Fragen mit nachvollziehbaren Gründen.":"این آمادگی سوال‌های واقع‌بینانه را با دلیل‌های قابل پیگیری وصل می‌کند.","Sind beide Fragen konkret formuliert?":"آیا هر دو سوال مشخص نوشته شده‌اند؟","Betreffen sie Einarbeitung und Dienstplan getrennt?":"آیا آن‌ها جداگانه به آموزش اولیه و برنامهٔ کار مربوط‌اند؟","Erklärst du den eigenen Informationsbedarf?":"آیا نیاز خود به معلومات را توضیح می‌دهید؟","Vermeidest du die Annahme einer schon erfolgten Einstellung?":"آیا از فرض یک استخدام انجام‌شده پرهیز می‌کنید؟","Eine eigene Frage schließt eine konkrete Informationslücke.":"یک سوال خودتان یک کمبود مشخص معلومات را پر می‌کند.","Ein Beispiel beschreibt nicht automatisch jede spätere Schicht.":"یک مثال خودکار هر نوبت بعدی را توصیف نمی‌کند.","Den ersten Arbeitstag vorbereiten":"آماده کردن روز اول کار","Du klärst Treffpunkt, Beginn, Ansprechperson und benötigte Unterlagen vor Arbeitsaufnahme.":"شما جای ملاقات، شروع، شخص تماس و اسناد لازم را پیش از شروع کار روشن می‌کنید.","Firmenadresse als genauen Treffpunkt ansehen":"آدرس شرکت را جای دقیق ملاقات دانستن","Falsch: Den Eingang ohne Prüfung selbst wählen. Richtig: Empfang, Gebäude und Kontaktperson aus der Startabsprache klären.":"اشتباه: دروازه را بدون بررسی خودتان انتخاب کنید. درست: پذیرش، ساختمان و شخص تماس را از توافق شروع روشن کنید.","Ungeforderte Daten vorsorglich senden":"فرستادن پیشگیرانهٔ داده‌های ناخواسته","Falsch: Sensible Unterlagen an eine ungeprüfte Adresse schicken. Richtig: Den bestätigten Bedarf und Übermittlungsweg verwenden.":"اشتباه: اسناد حساس را به یک آدرس بررسی‌نشده بفرستید. درست: نیاز تأییدشده و راه فرستادن را به کار ببرید.","Wo soll Nila sich melden?":"نیلا کجا باید خود را معرفی کند؟","Direkt bei Herrn Kunz ohne Anmeldung am Empfang.":"مستقیم نزد آقای کونتس بدون ثبت در پذیرش.","Am Firmensitz ohne Prüfung der genannten Kontaktperson.":"در مرکز شرکت بدون بررسی شخص تماس نام‌برده.","Am Empfang bei Frau Seifert.":"در پذیرش نزد خانم زایفرت.","Treffpunkt und Ansprechperson sind ausdrücklich vereinbart.":"جای ملاقات و شخص تماس صریحاً توافق شده‌اند.","Was gilt für die Arbeitskleidung im Beispiel?":"در مثال دربارهٔ لباس کار چه چیزی اعتبار دارد؟","Sie muss unabhängig von der Absprache selbst beschafft werden.":"باید بدون توجه به توافق خودتان آن را تهیه کنید.","Sie wird im Betrieb ausgegeben.":"در شرکت داده می‌شود.","Sie wird erst nach einer privaten Bestellung ausgegeben.":"فقط بعد از یک سفارش خصوصی داده می‌شود.","Die Teamleitung kündigt die Ausgabe der Kleidung vor Ort an.":"رهبر گروه دادن لباس در محل را اعلام می‌کند.","Was ist bei unklarem Eingang sinnvoll?":"اگر دروازه نامشخص است چه کاری معقول است؟","Den Treffpunkt über die bekannte Kontaktperson klären.":"جای ملاقات را از راه شخص تماس شناخته‌شده روشن کردن.","Den nächstgelegenen Eingang ohne Rückfrage verwenden.":"نزدیک‌ترین دروازه را بدون پرسیدن به کار بردن.","Die spätere Einarbeitungsperson als ersten Treffpunkt annehmen.":"شخص آموزش اولیهٔ بعدی را جای اول ملاقات فرض کردن.","Eine gezielte Klärung vermeidet falsche Wege und unbefugtes Betreten.":"یک روشن‌سازی هدفمند از راه‌های اشتباه و رفتن بی‌اجازه جلوگیری می‌کند.","Notiere für den ersten Tag vier Angaben: wann, wo, bei wem und was mitzubringen ist.":"برای روز اول چهار معلومات یادداشت کنید: چه وقت، کجا، نزد چه کسی و چه چیزی همراه بیاورید.","Den Beginn genau absprechen":"توافق دقیق شروع","Teamleitung: „Am Montag beginnen Sie um acht Uhr. Melden Sie sich bitte am Empfang bei Frau Seifert.“ Nila: „Soll ich Arbeitskleidung mitbringen?“ Teamleitung: „Die Kleidung wird hier ausgegeben. Bitte bringen Sie die vorher angeforderten Unterlagen mit.“ Nila: „Dann bestätige ich Montag, acht Uhr, Empfang bei Frau Seifert.“":"رهبر گروه: «دوشنبه ساعت هشت شروع می‌کنید. لطفاً در پذیرش نزد خانم زایفرت خود را معرفی کنید.» نیلا: «لباس کار همراه بیاورم؟» رهبر گروه: «لباس اینجا داده می‌شود. لطفاً اسنادی را که قبلاً خواسته شده همراه بیاورید.» نیلا: «پس دوشنبه، ساعت هشت، پذیرش نزد خانم زایفرت را تأیید می‌کنم.»","Eine klare Startnotiz anlegen":"ساختن یک یادداشت روشن شروع","Eine bestätigte Arbeitsaufnahme braucht praktische Vorbereitung. Übertrage die vereinbarten Angaben in eine kurze Notiz und prüfe die Anfahrt zur tatsächlichen Uhrzeit. Ein allgemeiner Firmensitz ist nicht zwingend der richtige Eingang. Frage bei fehlender Treffpunktangabe nach. Wenn du dich verspätest, informiere die geklärte Kontaktperson frühzeitig mit einer realistischen Einschätzung.":"یک شروع کار تأییدشده آمادگی عملی لازم دارد. معلومات توافق‌شده را در یک یادداشت کوتاه بنویسید و راه رسیدن را در همان ساعت واقعی بررسی کنید. یک مرکز عمومی شرکت لزوماً دروازهٔ درست نیست. اگر جای ملاقات گفته نشده، بپرسید. اگر دیر می‌رسید، شخص تماس روشن‌شده را زود با یک برآورد واقع‌بینانه خبر کنید.","Mitbringliste nicht erfinden":"لست همراه آوردنی را نساختن","Bringe die vorher angeforderten Unterlagen über den vereinbarten Weg mit. Eine allgemeine Kursliste ersetzt keine Nachricht deines Betriebs. Fehlt eine Angabe, frage die Kontaktperson. Sende sensible Daten nicht vorsorglich an eine unbekannte Adresse. Notiere auch, ob Kleidung vor Ort ausgegeben wird oder ob du etwas mitbringen sollst.":"اسنادی را که قبلاً خواسته شده از راه توافق‌شده همراه بیاورید. یک لست عمومی کورس جای پیام شرکت شما را نمی‌گیرد. اگر یک معلومات کم است، از شخص تماس بپرسید. داده‌های حساس را پیشگیرانه به یک آدرس ناشناخته نفرستید. همچنین یادداشت کنید که آیا لباس در محل داده می‌شود یا باید چیزی همراه بیاورید.","Am Anfang aufmerksam nachfragen":"در آغاز با دقت پرسیدن","Plane Zeit für Anmeldung und Orientierung ein. Frage, wo persönliche Sachen abgelegt werden und wer die Einarbeitung begleitet. Eine höfliche Rückfrage ist besser als das Betreten eines unklaren Bereichs. Lass dir Aufgaben, Sicherheitsregeln und Zugänge im neuen Betrieb erklären. Vorerfahrung ersetzt diese Einführung nicht.":"برای ثبت و آشنایی وقت بگذارید. بپرسید وسایل شخصی کجا گذاشته می‌شوند و چه کسی آموزش اولیه را همراهی می‌کند. یک سوال مؤدبانه بهتر از رفتن به یک بخش نامشخص است. بگذارید کارها، قاعده‌های ایمنی و دسترسی‌ها در شرکت تازه برایتان توضیح داده شوند. تجربهٔ قبلی جای این آشنایی را نمی‌گیرد.","Die Startnotiz ergänzen":"کامل کردن یادداشت شروع","Setze „acht“ und „Empfang“ ein.":"„acht“ (هشت) و „Empfang“ (پذیرش) را بگذارید.","Übernimm Uhrzeit und Ort aus der Absprache.":"ساعت و جا را از توافق بگیرید.","Die Startnotiz enthält die bestätigten organisatorischen Angaben.":"یادداشت شروع معلومات سازمانی تأییدشده را دارد.","Beginn am Montag um ___ Uhr.":"Beginn am Montag um ___ Uhr. (شروع دوشنبه ساعت ___.)","Treffpunkt ist der ___.":"Treffpunkt ist der ___. (جای ملاقات ___ است.)","Vorbereitungen ordnen":"مرتب کردن آمادگی‌ها","Verbinde die Angabe mit der Frage.":"معلومات را به سوال وصل کنید.","Die kurzen Fragen verhindern wichtige Lücken.":"این سوال‌های کوتاه از کمبودهای مهم جلوگیری می‌کنند.","Zeit, Ort und Person beschreiben den Beginn eindeutig.":"وقت، جا و شخص شروع را روشن توصیف می‌کنند.","Montag um acht":"دوشنبه ساعت هشت","Empfang":"پذیرش","Frau Seifert":"خانم زایفرت","Die Ansprechperson verstehen":"فهمیدن شخص تماس","Bei wem soll Nila sich melden? Antworte mit Nachnamen.":"نیلا نزد چه کسی باید خود را معرفی کند؟ با نام خانوادگی جواب دهید.","Gesucht ist die erste Ansprechperson am Empfang.":"اولین شخص تماس در پذیرش پرسیده شده است.","Frau Seifert ist für die Anmeldung am Empfang genannt.":"خانم زایفرت (Seifert) برای ثبت در پذیرش نام برده شده است.","Den Arbeitsbeginn bestätigen":"تأیید شروع کار","Schreibe drei Sätze zu Beginn, Treffpunkt, Kleidung und angeforderten Unterlagen.":"سه جمله دربارهٔ شروع، جای ملاقات، لباس و اسناد خواسته‌شده بنویسید.","Die Bestätigung soll die Absprache wiedergeben, keine eigene neue Liste.":"تأیید باید توافق را نقل کند، نه یک لست تازهٔ خودتان را.","Die Notiz hält den praktischen Start vollständig und ohne erfundene Anforderungen fest.":"این یادداشت شروع عملی را کامل و بدون خواسته‌های ساختگی ثبت می‌کند.","Sind Tag und Uhrzeit korrekt?":"آیا روز و ساعت درست‌اند؟","Nennst du Empfang und Frau Seifert?":"آیا پذیرش و خانم زایفرت را نام می‌برید؟","Gibst du die Ausgabe der Kleidung richtig wieder?":"آیا دادن لباس را درست نقل می‌کنید؟","Beschränkst du die Unterlagen auf den bestätigten Bedarf?":"آیا اسناد را به نیاز تأییدشده محدود می‌کنید؟","Eine Startnotiz enthält Uhrzeit, Treffpunkt und Ansprechperson.":"یک یادداشت شروع ساعت، جای ملاقات و شخص تماس را دارد.","Die betriebliche Einführung gehört auch bei vorhandener Erfahrung zum Start.":"آشنایی در شرکت با وجود تجربهٔ موجود هم جزو شروع است.","Sicher eingearbeitet werden und nachfragen":"آموزش اولیهٔ مطمئن و پرسیدن","Du wiederholst einen neuen Ablauf und fragst vor einer unsicheren Handlung nach.":"شما یک روند تازه را تکرار می‌کنید و پیش از یک کار نامطمئن می‌پرسید.","Ähnliches Modell als vollständige Einweisung ansehen":"مدل مشابه را آموزش کامل دانستن","Falsch: Ohne Erklärung das neue Modell selbst starten. Richtig: Ablauf, Schutzmaßnahmen und zulässigen Tätigkeitsumfang klären.":"اشتباه: بدون توضیح مدل تازه را خودتان روشن کنید. درست: روند، اقدام‌های حفاظتی و اندازهٔ مجاز کار را روشن کنید.","Unsicherheit mit Nicken verdecken":"پوشاندن نامطمئن بودن با سر تکان دادن","Falsch: Zustimmung zeigen, obwohl die Abschaltung unklar ist. Richtig: Den fehlenden Schritt konkret nachfragen und zeigen lassen.":"اشتباه: موافقت نشان دهید، با اینکه خاموش کردن نامشخص است. درست: قدم کم را مشخص بپرسید و بگذارید نشان دهند.","Was macht Karim vor dem Start richtig?":"کریم پیش از روشن کردن چه کاری را درست انجام می‌دهد؟","Er startet, weil er bereits ein ähnliches Modell kennt.":"روشن می‌کند، چون از قبل یک مدل مشابه را می‌شناسد.","Er lässt sich die Abschaltung erneut zeigen.":"می‌خواهد خاموش کردن را دوباره به او نشان دهند.","Er übernimmt die Schritte der alten Maschine unverändert.":"قدم‌های ماشین قدیمی را بدون تغییر به کار می‌برد.","Er klärt einen sicherheitsrelevanten unbekannten Schritt vor der eigenen Handlung.":"او یک قدم ناشناختهٔ مهم برای ایمنی را پیش از کار خودش روشن می‌کند.","Woran lässt sich das Verständnis eines Ablaufs am besten prüfen?":"فهمیدن یک روند را چطور بهتر می‌توان بررسی کرد؟","Die Person erklärt den Ablauf in eigenen Worten und klärt offene Schritte.":"شخص روند را با کلمه‌های خودش توضیح می‌دهد و قدم‌های باز را روشن می‌کند.","Die Person nickt während der Erklärung zustimmend.":"شخص در وقت توضیح به نشان موافقت سر تکان می‌دهد.","Die Person kennt bereits ein ähnliches Maschinenmodell.":"شخص از قبل یک مدل مشابه ماشین را می‌شناسد.","Eine Erklärung in eigenen Worten macht das Verständnis prüfbar; Nicken und Vorerfahrung allein reichen dafür nicht.":"یک توضیح با کلمه‌های خود فهمیدن را قابل بررسی می‌کند؛ سر تکان دادن و تجربهٔ قبلی به تنهایی کافی نیستند.","Welche Rückfrage ist konkret?":"کدام سوال بعدی مشخص است؟","Ich glaube, eine ähnliche Abschaltung kenne ich schon.":"فکر می‌کنم یک خاموش کردن مشابه را از قبل می‌شناسم.","Kann ich die Abschaltung beim ersten eigenen Einsatz ausprobieren?":"می‌توانم خاموش کردن را در اولین کار خودم امتحان کنم؟","Bitte zeigen Sie mir die Abschaltung noch einmal.":"لطفاً خاموش کردن را یک بار دیگر به من نشان دهید.","Die Frage nennt den genauen Schritt, den Karim noch nicht sicher beherrscht.":"این سوال قدم دقیقی را نام می‌برد که کریم هنوز مطمئن بلد نیست.","Formuliere vor einer unbekannten Aufgabe: Was ist erklärt, was fehlt und wer kann es zeigen?":"پیش از یک کار ناشناخته بنویسید: چه چیزی توضیح داده شده، چه چیزی کم است و چه کسی می‌تواند آن را نشان دهد؟","Eine unbekannte Maschine nicht einfach bedienen":"یک ماشین ناشناخته را همین طوری به کار نبردن","Anleiterin: „Heute zeige ich Ihnen den Ablauf an dieser Maschine.“ Karim: „Ich kenne eine ähnliche Maschine, aber dieses Modell noch nicht.“ Anleiterin: „Dann gehen wir die Schritte gemeinsam durch.“ Karim: „Bevor ich selbst starte, möchte ich die Abschaltung noch einmal sehen.“ Anleiterin: „Gut, wir üben das zuerst zusammen.“":"راهنما: «امروز روند این ماشین را به شما نشان می‌دهم.» کریم: «یک ماشین مشابه را می‌شناسم، اما این مدل را هنوز نه.» راهنما: «پس قدم‌ها را با هم مرور می‌کنیم.» کریم: «پیش از اینکه خودم روشن کنم، می‌خواهم خاموش کردن را یک بار دیگر ببینم.» راهنما: «خوب، اول آن را با هم تمرین می‌کنیم.»","Erfahrung und Einweisung auseinanderhalten":"جدا نگه داشتن تجربه و آموزش","Vorerfahrung kann das Verstehen erleichtern. Sie ersetzt aber keine Erklärung der konkreten Maschine, ihrer Regeln und Zuständigkeiten. Wiederhole den Ablauf in eigenen Worten und frage nach, wenn ein Schritt unsicher ist. Ein freundliches Nicken beweist noch kein Verständnis. Die folgende selbstständige Tätigkeit muss dem im Betrieb tatsächlich geklärten Umfang entsprechen.":"تجربهٔ قبلی می‌تواند فهمیدن را آسان‌تر کند. اما جای توضیح ماشین مشخص، قاعده‌ها و مسئولیت‌هایش را نمی‌گیرد. روند را با کلمه‌های خودتان تکرار کنید و اگر یک قدم نامطمئن است، بپرسید. یک سر تکان دادن دوستانه هنوز فهمیدن را ثابت نمی‌کند. کار مستقل بعدی باید با اندازه‌ای که در شرکت واقعاً روشن شده جور باشد.","Unklare Schritte konkret benennen":"نام بردن مشخص قدم‌های نامشخص","Bei einer Einweisung zeigt dir eine zuständige Person die nötigen Arbeitsschritte und Schutzmaßnahmen. Frage genau nach dem unklaren Schritt. „Bitte zeigen Sie mir die Abschaltung noch einmal“ ist eine klare Bitte. Wiederhole danach den Ablauf in eigenen Worten. So kann die Anleiterin prüfen, ob ihr dasselbe meint.":"در یک آموزش (Einweisung) یک شخص مسئول قدم‌های لازم کار و اقدام‌های حفاظتی را به شما نشان می‌دهد. دقیقاً دربارهٔ قدم نامشخص بپرسید. „Bitte zeigen Sie mir die Abschaltung noch einmal“ (لطفاً خاموش کردن را یک بار دیگر به من نشان دهید) یک خواهش روشن است. بعد روند را با کلمه‌های خودتان تکرار کنید. به این ترتیب راهنما می‌تواند بررسی کند که آیا هر دو یک چیز را منظور دارید.","Lernstand und Freigabe unterscheiden":"جدا کردن سطح یادگیری و اجازه","Eine gezeigte Handlung ist nicht automatisch eine Erlaubnis für jeden späteren Einsatz. Halte fest, was gemeinsam geübt wurde und welche Rückfrage offen ist. Bei Unsicherheit stoppe vor dem unklaren Schritt und kläre ihn mit der zuständigen Person. Dieser Kurs gibt keine Bedienungsanleitung für reale Maschinen; er trainiert die Kommunikation während der Einweisung.":"یک کار نشان‌داده‌شده خودکار اجازه برای هر کار بعدی نیست. یادداشت کنید چه چیزی با هم تمرین شد و کدام سوال باز است. در نامطمئنی پیش از قدم نامشخص بایستید و آن را با شخص مسئول روشن کنید. این کورس راهنمای استفاده برای ماشین‌های واقعی نمی‌دهد؛ ارتباط در وقت آموزش را تمرین می‌کند.","Die Rückfrage ergänzen":"کامل کردن سوال بعدی","Setze „Abschaltung“ und „gemeinsam“ ein.":"„Abschaltung“ (خاموش کردن) و „gemeinsam“ (با هم) را بگذارید.","Die Wörter benennen unklaren Schritt und Lernform.":"این کلمه‌ها قدم نامشخص و شکل یادگیری را نام می‌برند.","Die Anleitung klärt den konkreten Ablauf vor selbstständiger Tätigkeit.":"راهنمایی روند مشخص را پیش از کار مستقل روشن می‌کند.","Karim möchte die ___ noch einmal sehen.":"Karim möchte die ___ noch einmal sehen. (کریم می‌خواهد ___ را یک بار دیگر ببیند.)","Die Schritte werden zuerst ___ geübt.":"Die Schritte werden zuerst ___ geübt. (قدم‌ها اول ___ تمرین می‌شوند.)","Lernhandlungen zuordnen":"وصل کردن کارهای یادگیری","Verbinde die Handlung mit ihrem Zweck.":"کار را به هدف آن وصل کنید.","Eine bloße Zustimmung zeigt weniger als eine erklärte Handlung.":"یک موافقت خالی کمتر از یک کار توضیح‌داده‌شده نشان می‌دهد.","Die Schritte machen den tatsächlichen Lernstand sichtbar.":"این قدم‌ها سطح واقعی یادگیری را قابل دید می‌کنند.","Ablauf wiederholen":"تکرار روند","unklaren Schritt nennen":"نام بردن قدم نامشخص","gemeinsam üben":"با هم تمرین کردن","Den unklaren Schritt erfassen":"ثبت قدم نامشخص","Welchen Schritt möchte Karim erneut sehen?":"کریم کدام قدم را دوباره می‌خواهد ببیند؟","Gesucht ist nicht der bereits verstandene Schritt.":"قدمی که از قبل فهمیده شده پرسیده نشده است.","Karim bittet ausdrücklich um erneutes Zeigen der Abschaltung.":"کریم صریحاً می‌خواهد خاموش کردن (Abschaltung) دوباره نشان داده شود.","Eine Einarbeitungsrückfrage formulieren":"نوشتن یک سوال آموزش اولیه","Schreibe drei Sätze: ähnliche Erfahrung, unbekanntes Modell und Bitte vor dem Start.":"سه جمله بنویسید: تجربهٔ مشابه، مدل ناشناخته و خواهش پیش از روشن کردن.","Benutze eine klare Bitte statt Unsicherheit zu verstecken.":"به جای پنهان کردن نامطمئنی یک خواهش روشن به کار ببرید.","Die Formulierung macht Lernbedarf und passenden nächsten Schritt sichtbar.":"این نوشته نیاز یادگیری و قدم بعدی مناسب را قابل دید می‌کند.","Unterscheidest du Vorerfahrung und konkretes Modell?":"آیا تجربهٔ قبلی و مدل مشخص را جدا می‌کنید؟","Nennst du die Abschaltung als offene Frage?":"آیا خاموش کردن را سوال باز نام می‌برید؟","Bittest du vor dem eigenen Start um Erklärung?":"آیا پیش از کار خودتان توضیح می‌خواهید؟","Bleibt der nächste Versuch unter Anleitung beschrieben?":"آیا آزمایش بعدی تحت راهنمایی توصیف شده می‌ماند؟","Ein bekannter Maschinentyp ersetzt die konkrete betriebliche Einweisung nicht.":"یک نوع ماشین شناخته‌شده جای آموزش مشخص در شرکت را نمی‌گیرد.","Eine präzise Rückfrage bezeichnet den tatsächlich unklaren Schritt.":"یک سوال دقیق قدم واقعاً نامشخص را نام می‌برد.","Rückmeldung einholen und den Lernstand festhalten":"گرفتن بازخورد و ثبت سطح یادگیری","Du besprichst nach den ersten Tagen Gelungenes, offene Fragen und einen konkreten Lernschritt.":"شما بعد از روزهای اول چیزهای موفق، سوال‌های باز و یک قدم مشخص یادگیری را صحبت می‌کنید.","Pauschales Urteil statt Lernfrage verwenden":"به کار بردن قضاوت کلی به جای سوال یادگیری","Falsch: „Ich kann nichts“, obwohl der normale Ablauf gelingt. Richtig: Gelungenen Ablauf und Unsicherheit beim Ausnahmefall getrennt nennen.":"اشتباه: „Ich kann nichts“ (هیچ کاری بلد نیستم)، با اینکه روند عادی موفق است. درست: روند موفق و نامطمئنی در حالت استثنایی را جدا نام ببرید.","Feedback als Vertragsänderung lesen":"بازخورد را تغییر قرارداد خواندن","Falsch: Aus einem Lernhinweis eine neue vertragliche Arbeitszeit ableiten. Richtig: Inhalt und Reichweite der Rückmeldung genau festhalten.":"اشتباه: از یک اشارهٔ یادگیری یک ساعت کار تازهٔ قراردادی نتیجه بگیرید. درست: محتوا و دامنهٔ بازخورد را دقیق ثبت کنید.","Was gelingt Ben bereits?":"بن چه کاری را از قبل موفق انجام می‌دهد؟","Die Warenannahme nach Checkliste.":"گرفتن کالا بر اساس چک‌لست.","Die Meldung beschädigter Verpackungen ohne Begleitung.":"گزارش بسته‌بندی‌های آسیب‌دیده بدون همراهی.","Die Entscheidung über alle Ausnahmen der Warenannahme.":"تصمیم دربارهٔ همهٔ استثناهای گرفتن کالا.","Ben beschreibt den normalen Ablauf als gelungen und grenzt den Ausnahmefall ab.":"بن روند عادی را موفق توصیف می‌کند و حالت استثنایی را جدا می‌کند.","Wen soll er bei beschädigter Verpackung informieren?":"در بسته‌بندی آسیب‌دیده به چه کسی باید خبر دهد؟","Direkt den Lieferanten ohne betrieblichen Meldeweg.":"مستقیم به تأمین‌کننده بدون راه گزارش شرکت.","Eine Kollegin ohne geklärte Zuständigkeit.":"به یک همکار بدون مسئولیت روشن‌شده.","Die Schichtleitung.":"به رهبر نوبت.","Die Leiterin nennt die Schichtleitung ausdrücklich als Kontakt.":"رهبر صریحاً رهبر نوبت (Schichtleitung) را شخص تماس می‌نامد.","Welche Rückmeldung wäre besonders hilfreich?":"کدام بازخورد به‌خصوص مفید است؟","Der Ablauf klappt wohl; weitere Angaben brauchen wir nicht.":"روند احتمالاً کار می‌کند؛ معلومات بیشتر لازم نداریم.","Die Checkliste ist vollständig; bei Schäden bitte die Schichtleitung informieren.":"چک‌لست کامل است؛ در آسیب‌ها لطفاً به رهبر نوبت خبر دهید.","Bei Schäden entscheide zunächst selbst und melde dich später.":"در آسیب‌ها اول خودت تصمیم بگیر و بعداً خبر بده.","Die Rückmeldung verbindet konkreten Fortschritt mit einem gezielten Hinweis.":"این بازخورد پیشرفت مشخص را با یک اشارهٔ هدفمند وصل می‌کند.","Bringe zum Rückmeldegespräch ein Beispiel für Fortschritt und eine klar benannte offene Aufgabe mit.":"به گفتگوی بازخورد یک مثال برای پیشرفت و یک کار باز روشن‌نام‌برده بیاورید.","Die erste Woche auswerten":"ارزیابی هفتهٔ اول","Leiterin: „Wie läuft es bisher?“ Ben: „Die Warenannahme klappt nach der Checkliste. Bei beschädigten Verpackungen bin ich noch unsicher, wen ich informieren soll.“ Leiterin: „Das melden Sie der Schichtleitung.“ Ben: „Dann notiere ich diesen Kontakt und bitte beim nächsten Fall um eine kurze Begleitung.“":"رهبر: «تا حالا چطور پیش می‌رود؟» بن: «گرفتن کالا با چک‌لست خوب پیش می‌رود. در بسته‌بندی‌های آسیب‌دیده هنوز مطمئن نیستم به چه کسی خبر بدهم.» رهبر: «این را به رهبر نوبت گزارش دهید.» بن: «پس این تماس را یادداشت می‌کنم و در مورد بعدی یک همراهی کوتاه می‌خواهم.»","Beobachtungen statt Gesamturteile nennen":"نام بردن دیده‌ها به جای قضاوت‌های کلی","„Alles schlecht“ und „alles perfekt“ helfen beim Lernen wenig. Beschreibe eine konkrete Tätigkeit und den noch unklaren Teil. Ben kann den normalen Ablauf, braucht aber Klarheit im Ausnahmefall. Frage nach einem beobachtbaren Kriterium: „Woran erkenne ich, dass die Dokumentation vollständig ist?“. So lässt sich Rückmeldung an einer tatsächlichen Aufgabe festmachen.":"„Alles schlecht“ (همه چیز بد) و „alles perfekt“ (همه چیز عالی) در یادگیری کم کمک می‌کنند. یک کار مشخص و بخش هنوز نامشخص را توصیف کنید. بن روند عادی را بلد است، اما در حالت استثنایی روشنی لازم دارد. دربارهٔ یک معیار قابل دیدن بپرسید: „Woran erkenne ich, dass die Dokumentation vollständig ist?“ (از کجا بفهمم که ثبت کامل است؟). به این ترتیب بازخورد را می‌توان به یک کار واقعی وصل کرد.","Nächste Schritte schriftlich sichern":"ثبت نوشتاری قدم‌های بعدی","Notiere die offene Aufgabe und die zuständige Person. Ben braucht Hilfe beim Melden beschädigter Verpackungen. Er hält deshalb die Schichtleitung als Kontakt fest. Außerdem vereinbart er Begleitung beim nächsten Fall. Ein solcher Lernhinweis ändert noch keine Vertragsbedingung. Schreibe nur auf, was im Gespräch wirklich vereinbart wurde.":"کار باز و شخص مسئول را یادداشت کنید. بن در گزارش بسته‌بندی‌های آسیب‌دیده کمک لازم دارد. به همین دلیل رهبر نوبت را شخص تماس ثبت می‌کند. علاوه بر آن برای مورد بعدی همراهی توافق می‌کند. چنین اشارهٔ یادگیری هنوز هیچ شرط قرارداد را تغییر نمی‌دهد. فقط چیزی را بنویسید که در گفتگو واقعاً توافق شد.","Fortschritt mit einer neuen Beobachtung prüfen":"بررسی پیشرفت با یک دیدهٔ تازه","Nach dem nächsten Fall vergleichst du, ob du den richtigen Kontakt gefunden und die Meldung verständlich gemacht hast. Falls noch eine Lücke besteht, frage erneut gezielt nach. Ein Lernplan wird nach Beobachtungen angepasst. Mit dem anschließenden Kurs zu Vertrag und Rechten ergänzt du die praktische Einarbeitung um das Verstehen wichtiger Arbeitsbedingungen.":"بعد از مورد بعدی مقایسه می‌کنید که آیا تماس درست را پیدا کرده‌اید و گزارش را قابل فهم داده‌اید. اگر هنوز کمبودی هست، دوباره هدفمند بپرسید. یک برنامهٔ یادگیری بر اساس دیده‌ها تطبیق داده می‌شود. با کورس بعدی دربارهٔ قرارداد و حقوق، آموزش اولیهٔ عملی را با فهمیدن شرط‌های مهم کار کامل می‌کنید.","Den Lernstand ergänzen":"کامل کردن سطح یادگیری","Setze „Checkliste“ und „Schichtleitung“ ein.":"„Checkliste“ (چک‌لست) و „Schichtleitung“ (رهبر نوبت) را بگذارید.","Trenne Hilfsmittel im Normalfall und Kontakt im Ausnahmefall.":"وسیلهٔ کمکی در حالت عادی و تماس در حالت استثنایی را جدا کنید.","Die Angaben machen den Lernstand praktisch nutzbar.":"این معلومات سطح یادگیری را عملاً قابل استفاده می‌کنند.","Die Warenannahme klappt nach der ___.":"Die Warenannahme klappt nach der ___. (گرفتن کالا با ___ خوب پیش می‌رود.)","Beschädigte Verpackungen meldet Ben der ___.":"Beschädigte Verpackungen meldet Ben der ___. (بن بسته‌بندی‌های آسیب‌دیده را به ___ گزارش می‌دهد.)","Rückmeldungsbausteine ordnen":"مرتب کردن بخش‌های بازخورد","Verbinde die Aussage mit ihrer Funktion.":"گفته را به کارکرد آن وصل کنید.","Die drei Angaben ergänzen sich zu einem Plan.":"این سه معلومات همدیگر را به یک برنامه کامل می‌کنند.","So wird ein pauschales Urteil durch konkrete Weiterarbeit ersetzt.":"به این ترتیب یک قضاوت کلی با کار مشخص بعدی جایگزین می‌شود.","Normalablauf gelingt":"روند عادی موفق است","Kontakt bei Schaden unklar":"تماس در آسیب نامشخص است","nächsten Fall begleiten lassen":"در مورد بعدی همراهی خواستن","Den offenen Punkt hören":"شنیدن نکتهٔ باز","Bei welchem Fall braucht Ben noch Unterstützung? Antworte mit zwei Wörtern.":"بن در کدام مورد هنوز حمایت لازم دارد؟ با دو کلمه (به آلمانی) جواب دهید.","Gesucht ist der Ausnahmefall.":"حالت استثنایی پرسیده شده است.","Der Lernbedarf betrifft die Meldung beschädigter Verpackungen.":"نیاز یادگیری به گزارش بسته‌بندی‌های آسیب‌دیده (beschädigte Verpackungen) مربوط است.","Eine Lernstandsnotiz schreiben":"نوشتن یک یادداشت سطح یادگیری","Schreibe vier Sätze zu Fortschritt, offenem Punkt, Kontakt und nächstem Übungsschritt.":"چهار جمله دربارهٔ پیشرفت، نکتهٔ باز، تماس و قدم تمرینی بعدی بنویسید.","Beschreibe den Stand mit beobachtbaren Handlungen.":"وضعیت را با کارهای قابل دیدن توصیف کنید.","Die Notiz verbindet Fortschritt und gezielte Einarbeitung.":"این یادداشت پیشرفت و آموزش اولیهٔ هدفمند را وصل می‌کند.","Nennst du einen konkreten Fortschritt?":"آیا یک پیشرفت مشخص را نام می‌برید؟","Ist die Unsicherheit auf den Ausnahmefall begrenzt?":"آیا نامطمئنی به حالت استثنایی محدود است؟","Hältst du die Schichtleitung als Kontakt fest?":"آیا رهبر نوبت را شخص تماس ثبت می‌کنید؟","Enthält der nächste Schritt eine anschließende Kontrolle?":"آیا قدم بعدی یک بررسی بعدی دارد؟","Eine konkrete Rückmeldung knüpft an beobachtbare Tätigkeiten an.":"یک بازخورد مشخص به کارهای قابل دیدن وصل می‌شود.","Ein Lernschritt nennt Aufgabe, Unterstützung und anschließende Prüfung.":"یک قدم یادگیری کار، حمایت و بررسی بعدی را نام می‌برد."};})(typeof window!=="undefined"?window:globalThis);
